# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ZEKÂT İBADETİNİN ANLAMI, HÜKMÜ VE FARZ OLMA ŞARTLARI</text>\n  <rect x="25" y="48" width="315" height="192" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="182" y="73" text-anchor="middle" font-size="13.5" font-weight="bold" fill="#1d4ed8">Zekâtın Tanımı ve Hükmü</text>\n  <text x="40" y="98" font-size="11.5" fill="#334155">• <tspan font-weight="bold" fill="#1e3a8a">Sözlük anlamı:</tspan> Temizlenme, arınma, artma,</text>\n  <text x="48" y="115" font-size="11.5" fill="#334155">çoğalma ve bereket demektir.</text>\n  <text x="40" y="138" font-size="11.5" fill="#334155">• <tspan font-weight="bold" fill="#1e3a8a">Terim anlamı:</tspan> Dinen zengin sayılan</text>\n  <text x="48" y="155" font-size="11.5" fill="#334155">Müslümanların yılda bir kez mallarının</text>\n  <text x="48" y="172" font-size="11.5" fill="#334155">belli miktarını ihtiyaç sahiplerine vermesidir.</text>\n  <text x="40" y="196" font-size="11.5" font-weight="bold" fill="#1d4ed8">• Hükmü: Farz (Hicretin 2. yılı / Medine)</text>\n  <text x="40" y="218" font-size="11.5" font-weight="bold" fill="#15803d">• Türü: Malî (mal ile yapılan) ibadettir.</text>\n  <rect x="360" y="48" width="315" height="192" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="517" y="73" text-anchor="middle" font-size="13.5" font-weight="bold" fill="#15803d">Zekât Kimlere Farzdır?</text>\n  <text x="375" y="98" font-size="11.5" fill="#334155">1. Müslüman, akıllı ve ergenlik çağına ulaşmış olmak</text>\n  <text x="375" y="121" font-size="11.5" fill="#334155">2. <tspan font-weight="bold" fill="#14532d">Asli (temel) ihtiyaçlar</tspan> ve borçlar dışında</text>\n  <text x="388" y="138" font-size="11.5" fill="#334155"><tspan font-weight="bold" fill="#14532d">nisap miktarı</tspan> mala sahip olmak</text>\n  <text x="375" y="161" font-size="11.5" fill="#334155">3. Malın üzerinden 1 kamerî yıl geçmesi</text>\n  <rect x="375" y="176" width="285" height="52" rx="6" fill="#dcfce7" stroke="#86efac"/>\n  <text x="517" y="194" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Asli İhtiyaçlardan Zekât Verilmez:</text>\n  <text x="517" y="212" text-anchor="middle" font-size="10.5" fill="#14532d">Oturulan ev, binek araç, giysi, gıda, meslek aletleri</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ZEKÂT VERİLECEK MALLAR, NİSAP MİKTARLARI VE ORANLARI</text>\n  <rect x="20" y="46" width="210" height="96" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="125" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#a16207">Altın, Para ve Ticaret Malı</text>\n  <text x="125" y="90" text-anchor="middle" font-size="11.5" fill="#334155">Nisap: <tspan font-weight="bold">85 g altın</tspan> (595 g gümüş)</text>\n  <text x="125" y="114" text-anchor="middle" font-size="13" font-weight="bold" fill="#854d0e">Oran: 1/40 (%2,5)</text>\n  <rect x="245" y="46" width="210" height="96" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="350" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">Küçükbaş Hayvanlar</text>\n  <text x="350" y="90" text-anchor="middle" font-size="11" fill="#334155">Nisap: <tspan font-weight="bold">40 koyun / keçi</tspan></text>\n  <text x="350" y="110" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e3a8a">40 - 120 arası: 1 koyun</text>\n  <text x="350" y="128" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e3a8a">121 - 200 arası: 2 koyun</text>\n  <rect x="470" y="46" width="210" height="96" rx="8" fill="#fdf2f8" stroke="#ec4899" stroke-width="1.5"/>\n  <text x="575" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#be185d">Büyükbaş ve Deve</text>\n  <text x="575" y="90" text-anchor="middle" font-size="11" fill="#334155">Sığır/Manda (30-39): <tspan font-weight="bold">1 buzağı (2 yaş)</tspan></text>\n  <text x="575" y="110" text-anchor="middle" font-size="11" fill="#334155">(40-59): <tspan font-weight="bold">1 dana (3 yaş)</tspan></text>\n  <text x="575" y="128" text-anchor="middle" font-size="11" font-weight="bold" fill="#9d174d">Deve: Her 5 deve için 1 koyun</text>\n  <rect x="20" y="154" width="435" height="90" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="237" y="176" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">Toprak Ürünleri (Öşür — Hasat Zamanı Verilir)</text>\n  <text x="35" y="200" font-size="11.5" fill="#334155">• Doğal yollarla (yağmur/nehir, masrafsız) sulanan: <tspan font-weight="bold" fill="#14532d">1/10 (%10)</tspan></text>\n  <text x="35" y="224" font-size="11.5" fill="#334155">• Emek ve sulama masrafıyla sulanan arazilerde: <tspan font-weight="bold" fill="#14532d">1/20 (%5)</tspan></text>\n  <rect x="470" y="154" width="210" height="90" rx="8" fill="#f3e8ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="575" y="178" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#7e22ce">Madenler</text>\n  <text x="575" y="202" text-anchor="middle" font-size="11" fill="#334155">Çıkarıldığı anda verilir</text>\n  <text x="575" y="224" text-anchor="middle" font-size="13" font-weight="bold" fill="#581c87">Oran: 1/5 (%20)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ZEKÂT HESAPLAMA ADIMLARI VE ÖRNEK UYGULAMALAR</text>\n  <rect x="30" y="52" width="305" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="182" y="78" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Altın ve Nakit Para Hesabı</text>\n  <text x="45" y="106" font-size="11.5" fill="#334155">1. Borçlar ve asli ihtiyaçlar düşülür.</text>\n  <text x="45" y="130" font-size="11.5" fill="#334155">2. Kalan miktar 85 g altından fazlaysa</text>\n  <text x="58" y="148" font-size="11.5" fill="#334155">40\'a bölünür (%2,5\'i alınır).</text>\n  <text x="45" y="176" font-size="11.5" font-weight="bold" fill="#1e3a8a">Örnek: 120.000 TL nakit birikim</text>\n  <text x="45" y="198" font-size="11.5" font-weight="bold" fill="#15803d">Zekât = 120.000 / 40 = 3.000 TL</text>\n  <rect x="365" y="52" width="305" height="185" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="517" y="78" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Toprak Ürünleri (Öşür) Hesabı</text>\n  <text x="380" y="106" font-size="11.5" fill="#334155">• 1 yıl bekleme şartı aranmaz, hasatta verilir.</text>\n  <text x="380" y="134" font-size="11.5" font-weight="bold" fill="#14532d">Örnek 1 (Yağmurla sulanan 4.000 kg buğday):</text>\n  <text x="390" y="154" font-size="11.5" fill="#334155">4.000 · (1/10) = 400 kg buğday</text>\n  <text x="380" y="182" font-size="11.5" font-weight="bold" fill="#14532d">Örnek 2 (Masrafla sulanan 4.000 kg mısır):</text>\n  <text x="390" y="202" font-size="11.5" fill="#334155">4.000 · (1/20) = 200 kg mısır</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
